import re

def parse_price(text):
if not isinstance(text, str):
raise ValueError("Unparseable price")

value = text.strip()

if value.lower() == "free":
    return 0.0

match = re.fullmatch(r"(?:[A-Za-z]{3}\s*)?(\d+(?:\.\d+)?)", value)

if not match:
    raise ValueError("Unparseable price")

return float(match.group(1))
